            const effectiveTz = personTz ?? teamTimeZone;
            const deliveryTime = calculateResultsReadyDeliveryTime(now, effectiveTz);
            const resultsJobId = JobId.make(`results-ready-${round.id}-${personId}`);

            yield* rounds.insertJob({
